CREATE TABLE `dev_raw.workable_postings` (
    id STRING NOT NULL OPTIONS(description="Workable's job shortcode ('shortcode', e.g. 'F8C64DEEC8'), present in both the list and the detail response. Unique per row: this is the merge key. The detail response also has a numeric 'id', kept only in raw_detail."),
    title STRING OPTIONS(description="Job title as published, from the list entry's 'title'. Not cleaned."),
    url STRING OPTIONS(description="Public URL of the posting, from the list entry's 'url'. The apply link ('application_url') is this URL plus '/apply' and is not stored."),
    city STRING OPTIONS(description="City as published, from the list entry's 'city'. Free text."),
    region STRING OPTIONS(description="Region/state as published, from the list entry's 'state' (renamed: 'state' in the detail response means the posting's status, e.g. 'published')."),
    country STRING OPTIONS(description="Country NAME as published, from the list entry's 'country', e.g. 'United States'. See country_code for the ISO form."),
    country_code STRING OPTIONS(description="ISO-3166 alpha-2 code of the first listed location, from 'locations[0].countryCode', e.g. 'US'. The same payload gives the country as a name AND as a code - both kept; further locations stay in raw."),
    telecommuting BOOL OPTIONS(description="Remote flag from the LIST response ('telecommuting'). Workable expresses remoteness three times across its two payloads: this, plus 'workplace' and 'remote' in the detail. The list flag is the only one available for every job every night."),
    department STRING OPTIONS(description="Department as published, from the list entry's 'department'. Often null (and the detail response has it as an array, usually empty)."),
    employment_type STRING OPTIONS(description="Employment type as published, from the list entry's 'employment_type', e.g. 'Full-time'. Workable's own spelling, NOT normalised: Lever says 'Full-Time', Ashby 'FullTime'. Mapping happens downstream."),
    education STRING OPTIONS(description="Required education as published, from the list entry's 'education', e.g. Bachelor's Degree. One of four taxonomy fields only Workable (and SmartRecruiters) provide; empty strings are stored as NULL."),
    experience STRING OPTIONS(description="Seniority as published, from the list entry's 'experience', e.g. 'Director', 'Mid-Senior level'. The only seniority signal among the sources loaded so far."),
    industry STRING OPTIONS(description="Industry as published, from the list entry's 'industry', e.g. 'Electrical/Electronic Manufacturing'."),
    job_function STRING OPTIONS(description="Job function as published, from the list entry's 'function' (renamed: 'function' reads like a SQL keyword)."),
    published_on DATE OPTIONS(description="Publication DATE from the list entry's 'published_on' ('2026-09-01'). Date only, no time: stored as DATE rather than a fabricated midnight timestamp. (The detail's 'published' is the same day at 00:00Z.)"),
    workplace STRING OPTIONS(description="Workplace as published, from the DETAIL response's 'workplace': 'on_site', 'hybrid', 'remote'. Richer than telecommuting, but only for jobs whose detail has been fetched."),
    language STRING OPTIONS(description="Posting language from the DETAIL response's 'language', e.g. 'en'."),
    content STRING OPTIONS(description="Job description from the DETAIL response's 'description'. HTML, stored unparsed. NULL until the job's detail has been fetched (see detail_fetched_at). Workable splits the text in three - this, 'requirements', 'benefits' - each kept as its own column, as other sources' sections are."),
    requirements STRING OPTIONS(description="Requirements section from the DETAIL response's 'requirements'. HTML."),
    benefits STRING OPTIONS(description="Benefits section from the DETAIL response's 'benefits'. HTML."),
    salary_min NUMERIC OPTIONS(description="Lower salary bound from the DETAIL response's 'salary_from' (flat fields here; Lever and Ashby nest salary in an object). NUMERIC: money is never a float. Absent from most postings."),
    salary_max NUMERIC OPTIONS(description="Upper salary bound from the DETAIL response's 'salary_to'."),
    salary_currency STRING OPTIONS(description="Currency from the DETAIL response's 'salary_currency_iso_code', ISO-4217."),
    salary_frequency STRING OPTIONS(description="Period the salary refers to, from the DETAIL response's 'salary_frequency', e.g. 'year'. Lever/Ashby say 'interval', Recruitee 'period'."),
    raw STRING NOT NULL OPTIONS(description="The job's entries from Workable's LIST response, as a JSON ARRAY. The list repeats a job once per location (one board: 1,905 entries for 318 jobs), each entry carrying only its own location; the row takes city/region/country from the first entry, and this array keeps every entry so no location is lost. Also holds list-only fields not flattened above (e.g. 'application_url', 'created_at')."),
    raw_detail STRING OPTIONS(description="The job's DETAIL response, as JSON text. NULL until fetched. Fetched once per job (and again after 30 days), not every night - see detail_fetched_at."),
    detail_fetched_at TIMESTAMP OPTIONS(description="When this job's detail response was last fetched (the landing time of that file). Pipeline-owned. Drives the incremental extract: jobs with a detail fetched in the last 30 days are not re-requested; NULL means the detail is still pending (the extract caps detail requests per run, so a large backlog clears over several nights). Detail columns are only ever overwritten by a newer fetch, never by a night that fetched nothing."),
    first_seen_at TIMESTAMP NOT NULL OPTIONS(description="When this job was FIRST seen in a landed file (the GCS object's creation time), not when the loader ran. Only ever moves earlier: re-loading an older day corrects it."),
    last_seen_at TIMESTAMP NOT NULL OPTIONS(description="When this job was MOST RECENTLY seen in a landed file (the GCS object's creation time). Only ever moves later. Workable publishes no 'updated_at', so this is the only freshness signal for list fields."),
    PRIMARY KEY (id) NOT ENFORCED
)
OPTIONS(description="One row per Workable job posting, holding its current state (not one row per ingestion). Built from TWO responses per job: the board's job list (every night) and the job's detail (only when not already held - fetched incrementally, capped per run, refreshed after 30 days). List columns follow the newest file; detail columns follow the newest DETAIL fetch, so a night without one never blanks them. Raw layer: values as published, flattened but not normalised. Loaded daily by the workable_ingestion DAG via dev_raw.workable_postings_incoming and a MERGE on id. Every response is kept in GCS (one file per board per run: the list plus that run's details, in an envelope).");
